INSERT INTO `enquiries` (`id`, `name`, `email`, `phone`, `subject`, `message`, `created_at`, `updated_at`, `view`, `region_code`) VALUES (1, 'Nishant Sharma', 'nishant.developer22@gmail.com', '1201201200', '1201201200', 'Hello team, "mydent.in"\\r\\n\\r\\nI just wanted to know if you require a better solution to manage SEO, SMO, SMM, PPC Campaigns, keyword research, Reporting etc. We are a leading Digital Marketing Agency, offering marketing solutions at affordable prices.\\r\\n\\r\\nWe can manage all as we have a 150+ expert team of professionals and help you save a hefty amount on hiring resources.\\r\\n\\r\\nWe can place your website on Google\'s 1st page. We will improve your website’s position on Google and get more traffic.\\r\\n\\r\\nI can send you more details on the packages/Portfolio/past work details.\\r\\n\\r\\n\\r\\nThank you,\\r\\n\\r\\n\\r\\nNishant Sharma', '2025-10-04 11:04:18', '2025-11-12 14:56:43', 1, NULL) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `enquiries` (`id`, `name`, `email`, `phone`, `subject`, `message`, `created_at`, `updated_at`, `view`, `region_code`) VALUES (2, 'Shaik Farhatulla', 'theinnerself3@gmail.com', '09849492909', 'SACD', 'sDFCVZCVZ', '2025-11-12 15:48:45', '2025-11-12 15:48:45', 0, NULL) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `enquiries` (`id`, `name`, `email`, `phone`, `subject`, `message`, `created_at`, `updated_at`, `view`, `region_code`) VALUES (3, 'Shaik Farhatulla', 'theinnerself3@gmail.com', '09849492909', 'SACD', 'sDFCVZCVZ', '2025-11-12 15:48:48', '2025-11-12 15:48:48', 0, NULL) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `enquiries` (`id`, `name`, `email`, `phone`, `subject`, `message`, `created_at`, `updated_at`, `view`, `region_code`) VALUES (4, 'Shaik Farhatulla', 'theinnerself3@gmail.com', '09849492909', 'SACD', 'sDFCVZCVZ', '2025-11-12 15:48:49', '2025-11-12 15:48:49', 0, NULL) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `enquiries` (`id`, `name`, `email`, `phone`, `subject`, `message`, `created_at`, `updated_at`, `view`, `region_code`) VALUES (5, 'AndrewWaync', 'no.reply.erikvincent@gmail.com', '84995786218', 'Reach your goals with the best advertising for your products and services!', 'Hey there! mydent.in \\r\\n \\r\\nDo you know that it is possible to send a letter in a completely legitimate way? \\r\\nWhen such appeals are sent, no personal data is used, and messages are sent to forms specifically designed to receive messages and appeals securely. Messages sent with Feedback Forms are not regarded as spam, as they are seen as crucial. \\r\\nWe offer you the chance to try out our service for free. \\r\\nWe can transmit up to 50,000 messages on your behalf. \\r\\n \\r\\nThe cost of sending one million messages is $59. \\r\\n \\r\\nThis message was automatically generated. \\r\\n \\r\\nContact us. \\r\\nTelegram - https://t.me/FeedbackFormEU \\r\\nWhatsApp - +375259112693 \\r\\nWhatsApp  https://wa.me/+375259112693 \\r\\nWe only use chat for communication.', '2026-03-06 02:31:49', '2026-03-06 02:31:49', 0, NULL) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `enquiries` (`id`, `name`, `email`, `phone`, `subject`, `message`, `created_at`, `updated_at`, `view`, `region_code`) VALUES (6, 'Olivier Gabriel Balzac', 'projectoffice111@gmail.com', '87657527992', 'I would greatly appreciate your response this time, as it is urgent.', 'Good day from France. \\r\\nIt is my pleasure to communicate with you again via this platform. Your positive response towards this very message is highly anticipated. \\r\\nMy name is Mr. Olivier Gabriel Balzac, a lawyer practicing here in France. I have previously sent you a latter regarding a transaction of US$13.5 Million left behind by my late client before his tragic death. However, I am reaching out to you once again because after going through your profile, I strongly believe that you will be in a better position to execute this business transaction with me. \\r\\nIf this interest you, kindly respond to me via my private email info@balzacavocate.com for more detail. I suggest after the transaction, we donate 5% of the money to charity organizations while the remaining 95% is shared equally between us. \\r\\nThis transaction is 100% risk free and I look forward to your response. \\r\\nYours sincerely \\r\\nOlivier Gabriel Balzac, \\r\\nLawyer. \\r\\nPhone. +33 756 850 084 \\r\\nE-mail: info@balzacavocate.com', '2026-03-26 21:07:39', '2026-03-26 21:07:39', 0, NULL) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `enquiries` (`id`, `name`, `email`, `phone`, `subject`, `message`, `created_at`, `updated_at`, `view`, `region_code`) VALUES (7, 'Aman Katiyar', 'aman@rocketdigitaltech.com', '7532833829', '7532833829', 'Hello http://mydent.in,\\r\\n \\r\\nWe can place your website on Google 1st page.\\r\\n \\r\\nI can give you our Complete SEO Action Plan along with a customary reach and add great value to your product/ service.\\r\\n \\r\\nI may send you a SEO Packages & price list. If interested.\\r\\n \\r\\nBest Regards,\\r\\nAman\\r\\nOnline SEO Consultant', '2026-05-06 08:48:24', '2026-05-06 08:48:24', 0, NULL) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `enquiries` (`id`, `name`, `email`, `phone`, `subject`, `message`, `created_at`, `updated_at`, `view`, `region_code`) VALUES (8, 'Asif Ali', 'asif@rocketdigitaltech.com', '7532833829', '7532833829', 'Hello http://mydent.in,\\r\\n \\r\\nIf you’re looking to boost your website’s visibility, I can help you achieve top Google rankings.\\r\\n \\r\\nI’ll prepare a complete SEO plan with actionable steps and potential growth insights for your products or services.\\r\\n \\r\\nOnce you share your target keywords and target market, I’ll send a full proposal.\\r\\n \\r\\nBest Regards,\\r\\nAsif', '2026-05-12 20:42:19', '2026-05-12 20:42:19', 0, NULL) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `enquiries` (`id`, `name`, `email`, `phone`, `subject`, `message`, `created_at`, `updated_at`, `view`, `region_code`) VALUES (9, 'Felix Lence', 'executive@sapmsllc.ae', '86373814869', 'Project Loan Funding', 'Greetings, \\r\\n \\r\\nWe are pleased to offer funding solutions to support your business growth. Our Loan Department provides financing for Working Capital, Start?ups, and expansion projects across sectors including Renewable Energy, Real Estate, Telecommunications, Infrastructure, Agriculture, Healthcare, and Oil & Gas. \\r\\n \\r\\nWe offer competitive rates and a fast, reliable application process. \\r\\n \\r\\nKindly respond at your earliest convenience so we can proceed with next steps. \\r\\n \\r\\nRegards \\r\\n \\r\\nFelix Lence \\r\\n \\r\\nFinancial Broker Authority to Anwar \\r\\nDohat Al-Adab Street, Al-Khuwair, \\r\\nMuscat, Sultanate of Oman \\r\\nW: +968 7503 9067 \\r\\nfelix.lence@anwarllc.com \\r\\nLevel 43, Building 115, King Abdullah Financial \\r\\nDistrict - Building Riyadh, Saudi Arabia – ETC', '2026-05-21 16:57:21', '2026-05-21 16:57:21', 0, NULL) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `enquiries` (`id`, `name`, `email`, `phone`, `subject`, `message`, `created_at`, `updated_at`, `view`, `region_code`) VALUES (10, 'Youssef Abdullah', 'yabdullah.agency@gmail.com', '87866844747', 'We are interested in your products', 'Seasons Greetings, \\r\\n \\r\\nWe are a Dubai-based business consulting and sourcing company with an extensive network of buyers, importers, distributors, and investors across the UAE and the Middle East. \\r\\n \\r\\nBased on the growing demand from our clients, we are seeking to establish business relationships with reputable manufacturers, traders, and distributors interested in expanding their products into the UAE market. \\r\\n \\r\\nThrough our network, we can introduce qualified buyers and business opportunities in sectors such as agriculture, manufacturing, construction, mining, oil and gas, consumer goods, and other industries. We conduct our business professionally and in full compliance with UAE laws and regulations. \\r\\n \\r\\nIf your company is interested in exploring cooperation opportunities, please send us your company profile, product e-catalog, and pricing information. We would be pleased to review your offerings and discuss potential business opportunities. \\r\\n \\r\\nContact me on this email address: yabdullah-agency@finvlimited.com \\r\\n \\r\\nKind regards, \\r\\nMr. Youssef Abdullah \\r\\nDubai Business Consultants', '2026-06-09 07:41:07', '2026-06-09 07:41:07', 0, NULL) ON DUPLICATE KEY UPDATE `id`=`id`;
